package com.library.server.service.impl; import com.library.common.model.PageResult; import com.library.pojo.entity.Admin; import com.library.server.mapper.AdminMapper; import com.library.server.service.AdminService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service public class AdminServiceImpl implements AdminService { private final AdminMapper mapper; private final PasswordEncoder encoder; public AdminServiceImpl(AdminMapper mapper,PasswordEncoder encoder){this.mapper=mapper;this.encoder=encoder;} public PageResult<Admin> page(String k,int p,int s){return new PageResult<>(mapper.count(k),p,s,mapper.page(k,(p-1)*s,s));} public void save(Admin x){if(x.getPassword()!=null)x.setPassword(encoder.encode(x.getPassword()));mapper.insert(x);} public void update(Admin x){if(x.getPassword()!=null&&!x.getPassword().isBlank())x.setPassword(encoder.encode(x.getPassword()));mapper.update(x);} public void delete(Long id){mapper.delete(id);} }
